"""
The text format the sheets are stored in (data/**/*.txt): one block per
sheet row and one line per non-empty cell, so `git diff` shows exactly
which cells of which rows changed.

    # GENERATED by scripts/sync_sheets.py from Google Sheets. Do not edit: ...
    # Sheet: https://docs.google.com/spreadsheets/d/.../edit?gid=0#gid=0
    # Tab: dhatu
    HEADER:type=record
    HEADER:key=src_link|dhatu
    HEADER:columns=src_link|dhatu|aupadeshika|gana_index|...

    .--- 01.0001 भू              record marker: '.--- ' + the key cell(s) (for reading only)
    .src_link: 01.0001           '.<column>: <value>', in the sheet's column order
    .dhatu: भू
    .artha: सत्तायाम्
    a second line of the same cell (lines after the first are written as they are)

  - HEADER:columns lists every column in sheet order, so the column layout
    (including columns that are empty in every row) survives the round trip.
  - Empty cells are left out; fully empty rows are dropped.
  - A column with no header, or a repeated header, is written by its
    position instead of its name, e.g. '.[G]: rm'.
  - A line starting with '.' is always a marker or a field, so a line in a
    cell (after its first line) can't start with '.'. The sync refuses such
    a sheet, naming the row and column.
  - Column names can't contain ':', '|' or a line break, or start with
    '-' or '['.

This is the same idea as the 'record' format in vagvibha/dict-builder,
except that row 1 of a kosha tab is the column header row (no metadata row).
"""

import re

MARKER = ".---"
MAX_REPORTED = 20
HEADER_RE = re.compile(r"^HEADER:([a-z]+)=(.*)$")
POS_RE = re.compile(r"^\[([A-Z]+)\]$")


class FormatError(Exception):
    pass


def column_letter(i):
    """0 -> A, 25 -> Z, 26 -> AA."""
    s, i = "", i + 1
    while i:
        i, r = divmod(i - 1, 26)
        s = chr(65 + r) + s
    return s


def column_index(letters):
    n = 0
    for ch in letters:
        n = n * 26 + ord(ch) - 64
    return n - 1


def field_names(header):
    """Header -> the name each column is written under ('[G]' for an
    unnamed or repeated column)."""
    counts = {}
    for h in header:
        counts[h] = counts.get(h, 0) + 1
    return [h if h and counts[h] == 1 else f"[{column_letter(j)}]" for j, h in enumerate(header)]


# ---------------------------------------------------------------- rows -> text
def rows_to_text(rows, comments=(), key=None):
    """Tidied, rectangular rows (row 0 = header) -> the file's text.
    `key`: the column, or list of columns, shown on each '.---' marker
    (default: the first column).
    Every problem is reported (up to MAX_REPORTED), by sheet row and column."""
    if not rows or not any(rows[0]):
        raise FormatError("the tab is empty (no header row)")
    header, data = rows[0], rows[1:]
    problems = []
    for j, h in enumerate(header):
        if h and (re.search(r"[:|\n]", h) or h[0] in "-["):
            problems.append(f"row 1, column {column_letter(j)}: column name {h!r} can't contain "
                            "':', '|' or a line break, or start with '-' or '['")
    names = field_names(header)
    keys = [key] if isinstance(key, str) else list(key or [header[0]])
    kjs = []
    for k in keys:
        if k not in header or names[header.index(k)] != k:
            raise FormatError(f"key column {k!r} is not a (unique) column; columns are {header}")
        kjs.append(header.index(k))

    out = [f"# {c}" for c in comments]
    out += ["HEADER:type=record", "HEADER:key=" + "|".join(keys), "HEADER:columns=" + "|".join(header)]
    for i, row in enumerate(data, start=2):
        if not any(row):
            continue
        label = " ".join(" ".join(row[j].split()) for j in kjs if row[j])
        out += ["", f"{MARKER} {label}".rstrip()]
        for j, cell in enumerate(row):
            if not cell:
                continue
            first, *rest = cell.split("\n")
            for k, line in enumerate(rest, start=2):
                if line.startswith("."):
                    problems.append(f"row {i}, column {column_letter(j)} ({header[j] or 'unnamed'}): "
                                    f"line {k} of the cell starts with '.' (not allowed after a "
                                    "cell's first line)")
            out.append(f".{names[j]}: {first}")
            out.extend(rest)
    if problems:
        more = len(problems) - MAX_REPORTED
        shown = problems[:MAX_REPORTED] + ([f"... and {more} more"] if more > 0 else [])
        raise FormatError("\n    ".join(["problems in the sheet:"] + shown))
    return "\n".join(out) + "\n"


# ---------------------------------------------------------------- text -> rows
def parse(text, filename="<text>"):
    """The file's text -> (headers {name: value}, rows) with rows[0] the
    column header and every row as wide as it."""
    def err(msg, n):
        return FormatError(f"{filename}:{n}: {msg}")

    lines = text.replace("\r\n", "\n").split("\n")
    headers, n = {}, 0
    while n < len(lines):
        line = lines[n]
        if line.startswith("#") or not line.strip():
            n += 1
            continue
        m = HEADER_RE.match(line)
        if not m:
            break
        if m.group(1) in headers:
            raise err(f"HEADER:{m.group(1)} given twice", n + 1)
        headers[m.group(1)] = m.group(2)
        n += 1
    if headers.get("type") != "record":
        raise err("not a record file (no HEADER:type=record)", 1)
    if "columns" not in headers:
        raise err("no HEADER:columns=", 1)
    header = headers["columns"].split("|")
    names = field_names(header)
    pos = {nm: j for j, nm in enumerate(names)}
    width = len(header)

    rows, rec, field = [header], None, None
    for n in range(n, len(lines)):
        line = lines[n]
        if line == MARKER or line.startswith(MARKER + " "):
            rec, field = [None] * width, None
            rows.append(rec)
        elif line.startswith("."):
            name, sep, value = line[1:].partition(": ")
            if not sep:
                raise err(f"bad line {line[:60]!r}: a line starting with '.' must be a "
                          f"'{MARKER} ...' record marker or a '.column: value' field", n + 1)
            if rec is None:
                raise err(f"field before the first '{MARKER}' record marker", n + 1)
            if name not in pos:
                raise err(f"unknown column {name!r} (not in HEADER:columns)", n + 1)
            field = pos[name]
            if rec[field] is not None:
                raise err(f"column {name!r} given twice in one record", n + 1)
            rec[field] = [value]
        elif field is not None:
            rec[field].append(line)
        elif line.strip():
            raise err(f"text outside a field (expected '{MARKER} ...' or '.column: value')", n + 1)
    for r in rows[1:]:
        for j, v in enumerate(r):
            r[j] = "\n".join(v).rstrip() if v is not None else ""
    return headers, rows


def read(path):
    """-> rows (row 0 = header) of a record file."""
    return parse(path.read_text(encoding="utf-8-sig"), str(path))[1]
